-- ============================================================
-- speaking_questions table & Cambridge 7-21 Authentic Question Bank
-- Generated by Cambridge Speaking Engine Audit System
-- ============================================================

CREATE TABLE IF NOT EXISTS public.speaking_questions (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source_type        text NOT NULL CHECK (source_type IN ('cambridge', 'mock_series')),
    book_or_set_number integer NOT NULL,
    test_number        integer NOT NULL CHECK (test_number BETWEEN 1 AND 4),
    module_type        text NOT NULL CHECK (module_type IN ('academic', 'general')),
    part_number        integer NOT NULL CHECK (part_number BETWEEN 1 AND 3),
    topic_title        text NOT NULL,
    cue_card_topic     text,
    prompts            jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at         timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_speaking_questions_unique
    ON public.speaking_questions (source_type, book_or_set_number, test_number, module_type, part_number);

CREATE INDEX IF NOT EXISTS idx_speaking_questions_lookup
    ON public.speaking_questions (source_type, book_or_set_number, test_number);

ALTER TABLE public.speaking_questions ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'speaking_questions' AND policyname = 'Anyone can read speaking questions'
    ) THEN
        CREATE POLICY "Anyone can read speaking questions"
            ON public.speaking_questions
            FOR SELECT
            USING (true);
    END IF;
END
$$;

ON CONFLICT (source_type, book_or_set_number, test_number, module_type, part_number)
DO UPDATE SET
    topic_title = EXCLUDED.topic_title,
    cue_card_topic = EXCLUDED.cue_card_topic,
    prompts = EXCLUDED.prompts;
